// Some portions generated by Codex
package org.eclipse.rdf4j.workbench.security;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;

import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;
import org.springframework.mock.web.MockHttpSession;

import jakarta.servlet.http.Cookie;

class WorkbenchCredentialSessionSecurityTest {

	@Test
	void storesCredentialsOnlyInTheBoundHttpSession() {
		WorkbenchCredentialSession credentials = new WorkbenchCredentialSession();
		MockHttpServletRequest request = secureRequest();
		String originalSessionId = request.getSession().getId();
		MockHttpServletResponse response = new MockHttpServletResponse();

		credentials.replace(request, response, "https://one.example/server", "alice smith", "super-secret");

		assertThat(credentials.read(request, new MockHttpServletResponse(), "https://one.example/server"))
				.isEqualTo(new WorkbenchCredentialSession.Credentials("alice smith", "super-secret"));
		assertThat(credentials.read(request, new MockHttpServletResponse(), "https://two.example/server")).isNull();
		assertThat(request.getSession().getId()).isNotEqualTo(originalSessionId);
		assertThat(Arrays.stream(response.getCookies()).map(Cookie::getValue))
				.noneMatch(value -> value.contains("super-secret"));
		assertThat(credentials.read(request, new MockHttpServletResponse(), "https://one.example/server").toString())
				.doesNotContain("super-secret");

		Cookie display = cookie(response, WorkbenchCredentialSession.DISPLAY_USERNAME_COOKIE);
		assertThat(display.getValue()).isEqualTo("alice%20smith");
		assertThat(display.isHttpOnly()).isFalse();
		assertThat(display.getSecure()).isTrue();
		assertThat(display.getAttribute("SameSite")).isEqualTo("Strict");

		Cookie legacyDeletion = cookie(response, WorkbenchCredentialSession.LEGACY_CREDENTIAL_COOKIE);
		assertThat(legacyDeletion.getValue()).isEmpty();
		assertThat(legacyDeletion.getMaxAge()).isZero();
		assertThat(legacyDeletion.isHttpOnly()).isTrue();
		assertThat(legacyDeletion.getSecure()).isTrue();
		assertThat(legacyDeletion.getAttribute("SameSite")).isEqualTo("Strict");
	}

	@Test
	void migratesAndExpiresAValidLegacyCredentialCookie() {
		WorkbenchCredentialSession credentials = new WorkbenchCredentialSession();
		MockHttpServletRequest request = secureRequest();
		String legacy = Base64.getEncoder()
				.encodeToString("alice:p:a:ssword".getBytes(StandardCharsets.UTF_8));
		request.setCookies(new Cookie(WorkbenchCredentialSession.LEGACY_CREDENTIAL_COOKIE, legacy));
		MockHttpServletResponse response = new MockHttpServletResponse();

		assertThat(credentials.read(request, response, "https://one.example/server"))
				.isEqualTo(new WorkbenchCredentialSession.Credentials("alice", "p:a:ssword"));
		assertThat(cookie(response, WorkbenchCredentialSession.LEGACY_CREDENTIAL_COOKIE).getMaxAge()).isZero();

		request.setCookies();
		assertThat(credentials.read(request, new MockHttpServletResponse(), "https://one.example/server"))
				.isEqualTo(new WorkbenchCredentialSession.Credentials("alice", "p:a:ssword"));
	}

	@Test
	void alwaysExpiresALingeringLegacyCookieWithoutOverwritingSessionCredentials() {
		WorkbenchCredentialSession credentials = new WorkbenchCredentialSession();
		MockHttpServletRequest request = secureRequest();
		credentials.replace(request, new MockHttpServletResponse(), "https://one.example/server", "alice", "current");
		request.setCookies(new Cookie(WorkbenchCredentialSession.LEGACY_CREDENTIAL_COOKIE,
				Base64.getEncoder().encodeToString("mallory:stale".getBytes(StandardCharsets.UTF_8))));
		MockHttpServletResponse response = new MockHttpServletResponse();

		assertThat(credentials.read(request, response, "https://one.example/server"))
				.isEqualTo(new WorkbenchCredentialSession.Credentials("alice", "current"));
		assertThat(cookie(response, WorkbenchCredentialSession.LEGACY_CREDENTIAL_COOKIE).getMaxAge()).isZero();
	}

	@Test
	void staleLegacyCookieCannotRebindExistingSessionCredentialsToAnotherServer() {
		WorkbenchCredentialSession credentials = new WorkbenchCredentialSession();
		MockHttpServletRequest request = secureRequest();
		credentials.replace(request, new MockHttpServletResponse(), "https://one.example/server", "alice", "current");
		request.setCookies(new Cookie(WorkbenchCredentialSession.LEGACY_CREDENTIAL_COOKIE,
				Base64.getEncoder().encodeToString("mallory:stale".getBytes(StandardCharsets.UTF_8))));
		MockHttpServletResponse response = new MockHttpServletResponse();

		assertThat(credentials.read(request, response, "https://two.example/server")).isNull();
		assertThat(cookie(response, WorkbenchCredentialSession.LEGACY_CREDENTIAL_COOKIE).getMaxAge()).isZero();

		request.setCookies();
		assertThat(credentials.read(request, new MockHttpServletResponse(), "https://one.example/server"))
				.isEqualTo(new WorkbenchCredentialSession.Credentials("alice", "current"));
	}

	@Test
	void replacementRotatesTheSessionAndSessionExpiryDropsCredentials() {
		WorkbenchCredentialSession credentials = new WorkbenchCredentialSession();
		MockHttpServletRequest request = secureRequest();
		credentials.replace(request, new MockHttpServletResponse(), "https://one.example/server", "alice", "first");
		String firstCredentialSessionId = request.getSession().getId();

		credentials.replace(request, new MockHttpServletResponse(), "https://one.example/server", "alice", "second");

		assertThat(request.getSession().getId()).isNotEqualTo(firstCredentialSessionId);
		assertThat(credentials.read(request, new MockHttpServletResponse(), "https://one.example/server"))
				.isEqualTo(new WorkbenchCredentialSession.Credentials("alice", "second"));

		request.getSession().invalidate();
		MockHttpServletRequest afterExpiry = new MockHttpServletRequest();
		afterExpiry.setSecure(true);
		afterExpiry.setContextPath("/workbench");
		assertThat(credentials.read(afterExpiry, new MockHttpServletResponse(), "https://one.example/server")).isNull();
	}

	@Test
	void rejectsMalformedLegacyCookiesAndAnonymousReplacementClearsState() {
		WorkbenchCredentialSession credentials = new WorkbenchCredentialSession();
		MockHttpServletRequest malformed = secureRequest();
		malformed.setCookies(new Cookie(WorkbenchCredentialSession.LEGACY_CREDENTIAL_COOKIE, "not-credentials"));
		MockHttpServletResponse malformedResponse = new MockHttpServletResponse();

		assertThat(credentials.read(malformed, malformedResponse, "https://one.example/server")).isNull();
		assertThat(cookie(malformedResponse, WorkbenchCredentialSession.LEGACY_CREDENTIAL_COOKIE).getMaxAge()).isZero();

		MockHttpServletRequest request = secureRequest();
		credentials.replace(request, new MockHttpServletResponse(), "https://one.example/server", "alice", "secret");
		MockHttpServletResponse clearResponse = new MockHttpServletResponse();
		credentials.replace(request, clearResponse, "https://one.example/server", "", "ignored");

		assertThat(credentials.read(request, new MockHttpServletResponse(), "https://one.example/server")).isNull();
		assertThat(cookie(clearResponse, WorkbenchCredentialSession.DISPLAY_USERNAME_COOKIE).getMaxAge()).isZero();
	}

	private static MockHttpServletRequest secureRequest() {
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.setSecure(true);
		request.setContextPath("/workbench");
		request.setSession(new MockHttpSession());
		return request;
	}

	private static Cookie cookie(MockHttpServletResponse response, String name) {
		return Arrays.stream(response.getCookies())
				.filter(cookie -> name.equals(cookie.getName()))
				.findFirst()
				.orElseThrow();
	}
}
